const error = $input.first().json;

const summary = {
  workflowName: error.workflow?.name || 'Unknown',
  workflowId: error.workflow?.id || 'Unknown',
  executionId: error.execution?.id || 'Unknown',
  errorMessage: error.execution?.error?.message || 'No error message',
  errorNode: error.execution?.lastNodeExecuted || 'Unknown',
  timestamp: new Date().toISOString(),
  retryUrl: error.execution?.url || null
};

console.error(`[LendLoop Error] Workflow '${summary.workflowName}' failed at node '${summary.errorNode}': ${summary.errorMessage}`);

return [{ json: summary }];
